#ifndef VRC_ABI_MANIFEST_BINDINGSOURCE_H
#define VRC_ABI_MANIFEST_BINDINGSOURCE_H

#include "llvm/ADT/StringRef.h"
#include "llvm/Support/Error.h"
#include "llvm/Support/JSON.h"
#include <string>

namespace vrc {

// Emits the low-level U# transport for the public export ABI in manifest.
// The manifest and source are deliberately generated by the compiler from the
// same recovered MLIR ABI; Unity only imports the returned source.
llvm::Expected<std::string>
buildUdonSharpBindingSource(const llvm::json::Object &manifest,
                            llvm::StringRef namespaceName,
                            llvm::StringRef className);

} // namespace vrc

#endif
